export const FIELDS='uptime_ms,sequence,sample_event,pulse_us,raw_mm,filtered_mm,depth_mm,depth_percent,sample_age_ms,validity,permission,reason,capture_overruns'.split(',');
export function csvSplit(line){const out=[];let part='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){part+='"';i++;}else quote=!quote;}else if(c===','&&!quote){out.push(part);part='';}else part+=c;}if(quote)return null;out.push(part);return out;}
export function parseLine(line,header=null){line=line.trim();if(line.includes('# water-monitor')){const config={};for(const v of line.slice(line.indexOf('# water-monitor')).split(',').slice(2)){const i=v.indexOf('=');if(i>0)config[v.slice(0,i)]=v.slice(i+1);}return {type:'config',config};}const cells=csvSplit(line);if(!cells)return null;if(cells.includes('uptime_ms')&&cells.includes('validity'))return {type:'header',header:cells};const fields=header||FIELDS;if(cells.length!==fields.length)return null;const row={};for(const k of FIELDS){const ix=fields.indexOf(k);if(ix<0)return null;row[k]=cells[ix];}for(const k of FIELDS.filter(k=>!['validity','reason'].includes(k))){if(!/^-?\d+$/.test(row[k]))return null;row[k]=Number(row[k]);if(!Number.isSafeInteger(row[k])||row[k]< (k==='sample_age_ms'?-1:0))return null;}if(![0,1].includes(row.sample_event)||![0,1].includes(row.permission)||row.depth_percent>100)return null;if(!['UNKNOWN','VALID','INVALID','STALE','UNCONFIGURED'].includes(row.validity))return null;if(!['STARTUP','READY','LOW','RECOVERING','RANGE','PULSE','TIMEOUT','CONFIG','CAPTURE'].includes(row.reason))return null;return {type:'row',row};}
export function presentation(row,config={},fresh=true){if(!row)return {kind:'idle',title:'Your instrument is ready. Connect to begin.',text:'Close Serial Monitor, use desktop Chrome or Edge, and select the Uno USB port. No firmware change needed.',levelValid:false,allowed:false};const minimum=Number(config.min_distance||300), maximum=Number(config.max_distance||4999);const timeout=Number(config.timeout||1000);if(!fresh)return {kind:'danger',title:'Live data stopped arriving.',text:'The last reading is historical. Check USB and reconnect; permission is unavailable.',levelValid:false,allowed:false};if(row.raw_mm===0)return {kind:'warning',title:'Waiting for a sensor measurement.',text:'Check sensor power, common ground, and serial output to Uno D8. Keep its control wire disconnected.',levelValid:false,allowed:false};if(row.raw_mm<=minimum)return {kind:'warning',title:'The target may be too close.',text:`${row.raw_mm} mm is at or below the configured minimum. Raise the sensor and check for the bucket rim or nearby objects.`,levelValid:false,allowed:false};if(row.raw_mm>maximum)return {kind:'warning',title:'No usable target detected.',text:'Aim the sensing face straight down at a clear water surface. Check the air gap and surrounding objects.',levelValid:false,allowed:false};if(row.validity==='UNCONFIGURED')return {kind:'warning',title:'Distance is arriving. Tank geometry is not configured.',text:'Raw ranging works, but water depth and irrigation permission require measured dimensions in config.h.',levelValid:false,allowed:false};if(row.validity!=='VALID'||row.sample_age_ms<0||row.sample_age_ms>=timeout)return {kind:'danger',title:'This reading is not valid for a water-level decision.',text:`Firmware reports ${row.validity} / ${row.reason}. Permission is blocked or unavailable.`,levelValid:false,allowed:false};return {kind:row.permission?'good':'warning',title:row.permission?'Water available. Monitoring is healthy.':row.reason==='LOW'?'Low water. Irrigation permission is blocked.':'Waiting for confirmed recovery.',text:row.permission?'The monitor allows irrigation; actual pump actuation is not connected.':'The monitor requires sufficient water and consecutive healthy readings before restoring permission.',levelValid:true,allowed:row.permission===1};}
